// Z. Bern, L. Dixon, D.A. Kosower, e-Print:hep-ph/9708239
// Eq8.14

namespace {
  std::complex<double> FPMFsc_unsym(int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb);
}

std::complex<double> FPMFsc(int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
  // @coverage-probe
  return FPMFsc_unsym(j1, j2, j3, j4, j5, j6, za, zb)
       + FPMFsc_unsym(j4, j3, j2, j1, j6, j5, zb, za);
}

namespace {
  std::complex<double> FPMFsc_unsym(int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
    auto zab2 = [&za, &zb](int i1, int i2, int i3, int i4) {
      return za(i1,i2)*zb(i2,i4) + za(i1,i3)*zb(i3,i4);
    };
    auto zab = [&za, &zb](int i1, int i2, int i3) {
      return za(i1,i2)*zb(i2,i3);
    };

    return -0.5*za(j1,j3)
        / (za(j1,j2)*za(j2,j3)*zb(j5,j6)*t(j1,j2,j3)*zab2(j1,j2,j3,j4))
        * (std::pow(za(j3,j2)*zb(j2,j1)*zab2(j1,j2,j3,j6), 2)
             * L1(-t(j1,j2,j3), -s(j2,j3)) / std::pow(s(j2,j3), 2)
           + std::pow(zab(j3,j4,j6), 2) * L1(-s(j5,j6), -t(j1,j2,j3)))
        + 0.5*std::pow(zb(j6,j2), 2) / (za(j1,j2)*zb(j2,j3)*zb(j3,j4)*zb(j5,j6));
    // +flip1
  }
}

extern "C" {
  std::complex<double> FPMFsc_wrapper(int j1, int j2, int j3, int j4, int j5, int j6, std::complex<double>* fza, std::complex<double>* fzb) {
    FArray2D<std::complex<double>> za(fza, mxpart, mxpart);
    FArray2D<std::complex<double>> zb(fzb, mxpart, mxpart);
    return FPMFsc(j1, j2, j3, j4, j5, j6, za, zb);
  }
}
