#define FPFPCC_H

#include <complex>
#include <FArray.hpp>

extern std::complex<double> FPFPcc(int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb);

extern "C" {
  extern std::complex<double> FPFPcc_wrapper(int j1, int j2, int j3, int j4, int j5, int j6, std::complex<double>* fza, std::complex<double>* fzb);
}

#endif

#include <FPFPcc.hpp>

#include <cmath>
#include <complex>
#include <FArray.hpp>
#include <mxpart_mod.hpp>
#include <sprods_com_mod.hpp>
#include <Need.hpp>
#include <W1jet.hpp>

using namespace mxpart_mod;
using namespace sprods_com_mod;

// Z. Bern, L. Dixon, D.A. Kosower, e-Print:hep-ph/9708239
// Eq9.4

namespace {
  std::complex<double> FPFPcc1(int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb);
  std::complex<double> FPFPcc2(int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb);
  std::complex<double> FPFPcc3(int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb);
}

std::complex<double> FPFPcc(int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
  double s234 = t(j2, j3, j4);

  // @coverage-probe
  return za(j3,j5)*(za(j2,j3)*za(j4,j5)+za(j3,j4)*za(j5,j2))
       / (za(j1,j2)*za(j3,j4)*za(j5,j6)*std::pow(za(j2,j4), 2))
       * Lsm1(-s(j2,j3), -s234, -s(j3,j4), -s234)

       - za(j1,j3)*std::pow(za(j3,j5), 2)
       / (za(j1,j2)*za(j2,j3)*za(j3,j4)*za(j4,j1)*za(j5,j6))
       * Lsm1(-s(j1,j2), -t(j1,j2,j3), -s(j2,j3), -t(j1,j2,j3))

       + za(j1,j3)*za(j3,j5)*(za(j1,j3)*za(j4,j5)+za(j3,j4)*za(j5,j1))
       / (za(j1,j2)*za(j2,j3)*za(j3,j4)*std::pow(za(j4,j1), 2)*za(j5,j6))
       * Lsm1_2me(t(j1,j2,j3), s234, s(j2,j3), s(j5,j6))

       - za(j1,j3)*std::pow(za(j3,j5), 2)
       / (za(j1,j2)*za(j2,j3)*za(j3,j4)*za(j4,j1)*za(j5,j6))
       * Lsm1_2me(t(j1,j2,j4), t(j1,j2,j3), s(j1,j2), s(j5,j6))

       - std::pow(za(j3,j5), 2) / (za(j2,j3)*za(j4,j1)*za(j5,j6)*za(j2,j4))
       * Lsm1(-s(j1,j4), -t(j1,j2,j4), -s(j1,j2), -t(j1,j2,j4))

       + FPFPcc1(j1,j2,j3,j4,j5,j6,za,zb)*L0(-s234,-s(j2,j3))/s(j2,j3)
       + FPFPcc2(j1,j2,j3,j4,j5,j6,za,zb)*L0(-s234,-s(j3,j4))/s(j3,j4)
       + FPFPcc3(j1,j2,j3,j4,j5,j6,za,zb)*L0(-s234,-s(j5,j6))/s(j5,j6);
}

namespace {
  std::complex<double> FPFPcc1(int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
    auto zab = [&za, &zb](int i1, int i2, int i3) {
      return za(i1,i2)*zb(i2,i3);
    };

    return -2.0*za(j3,j5)*zab(j5,j4,j2) / (za(j4,j1)*za(j5,j6)*za(j2,j4));
  }

  std::complex<double> FPFPcc2(int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
    auto zab = [&za, &zb](int i1, int i2, int i3) {
      return za(i1,i2)*zb(i2,i3);
    };

    return -2.0*za(j3,j5)*zab(j5,j2,j4) / (za(j1,j2)*za(j5,j6)*za(j2,j4));
  }

  std::complex<double> FPFPcc3(int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
    auto zab2 = [&za, &zb](int i1, int i2, int i3, int i4) {
      return za(i1,i2)*zb(i2,i4) + za(i1,i3)*zb(i3,i4);
    };

    return 2.0*za(j1,j3)*za(j5,j1)*za(j5,j3)*zab2(j3,j2,j4,j1)
         / (za(j1,j2)*za(j2,j3)*za(j3,j4)*za(j4,j1)*za(j5,j6));
  }
}

extern "C" {
  std::complex<double> FPFPcc_wrapper(int j1, int j2, int j3, int j4, int j5, int j6, std::complex<double>* fza, std::complex<double>* fzb) {
    FArray2D<std::complex<double>> za(fza, mxpart, mxpart);
    FArray2D<std::complex<double>> zb(fzb, mxpart, mxpart);
    return FPFPcc(j1, j2, j3, j4, j5, j6, za, zb);
  }
}
